    locs=[]
    for base,dirs,files in os.walk(root):
        if "f2" in dirs: locs.append(os.path.relpath(os.path.join(base,"f2"),root))
    print(f"move folder f2 dest={d!r} => {r.stdout.strip()!r} f2loc={locs}")
    e.cleanup()

# dest same as source folder? move note to folder already containing same name note
