from probe2 import setup
import os, shutil
def trial(mod, cmd):
    e=setup()
    root=os.path.join(e.vault_base,"v1")
    mod(e,root)
    r=e.run(cmd)
    print("mod=%s cmd=%s => out=%r err=%r exit=%s" % (mod.__name__, cmd, r.stdout[:150], r.stderr[:250], r.returncode))
    e.cleanup()

def del_vault_dir(e,root): shutil.rmtree(root)
