struct Parser {
    chars: Vec<char>,
    pos: usize,
}

impl Parser {
    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }
    fn peek_at(&self, n: usize) -> Option<char> {
        self.chars.get(self.pos + n).copied()
    }
    fn bump(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }
    fn starts_with(&self, s: &str) -> bool {
        s.chars().enumerate().all(|(i, c)| self.peek_at(i) == Some(c))
    }
    fn expect_char(&mut self, c: char) -> Result<(), ()> {
        if self.bump() == Some(c) {
            Ok(())
        } else {
            Err(())
        }
    }
    fn skip_ws_inline(&mut self) {
        while matches!(self.peek(), Some(' ') | Some('\t')) {
            self.pos += 1;
        }
    }
    fn skip_ws_and_comments(&mut self) {
        loop {
            while matches!(self.peek(), Some(' ') | Some('\t') | Some('\n') | Some('\r')) {
                self.pos += 1;
            }
            if self.peek() == Some('#') {
                while let Some(c) = self.peek() {
                    if c == '\n' {
                        break;
                    }
                    self.pos += 1;
                }
            } else {
                break;
            }
        }
    }
    fn parse_root(&mut self) -> Result<Value, ()> {
        let mut root = Value::Table(Vec::new());
        let mut current_path: Vec<String> = Vec::new();
        let mut defined_tables: HashSet<String> = HashSet::new();
        loop {
            self.skip_ws_and_comments();
            let Some(c) = self.peek() else {
                return Ok(root);
            };
            if c == '[' {
                // table header
                self.bump();
                let is_array = if self.peek() == Some('[') {
                    self.bump();
                    true
                } else {
                    false
                };
                self.skip_ws_inline();
                let keys = self.parse_dotted_key()?;
                self.skip_ws_inline();
                self.expect_char(']')?;
                if is_array {
                    self.expect_char(']')?;
                }
                // Allow a comment / trailing ws until newline; parser loop will skip it.
                // But require end-ish: if next char is not ws/comment/newline, error.
                match self.peek() {
                    None | Some('\n') | Some('\r') | Some(' ') | Some('\t') | Some('#') => {}
                    _ => return Err(()),
                }
                let joined = keys.join(".");
                if is_array {
                    // Create/append an array element table at path.
                    append_array_table(&mut root, &keys)?;
                    current_path = keys;
                    // Track current path specially using a marker handled in assign:
                    // We encode array-table current path as the key path; assignment
                    // resolves to the last array element (see navigate_current).
                    // Use a sentinel prefix.
                    current_path.insert(0, "\u{1}ARRAY".to_string());
                } else {
                    if !defined_tables.insert(joined.clone()) {
                        return Err(());
                    }
                    ensure_table(&mut root, &keys)?;
                    current_path = keys;
                }
            } else {
                // key = value in current table
                let keys = self.parse_dotted_key()?;
                self.skip_ws_inline();
                self.expect_char('=')?;
                self.skip_ws_inline();
                let value = self.parse_value()?;
                self.skip_ws_inline();
                match self.peek() {
                    None | Some('\n') | Some('\r') | Some('#') => {}
                    _ => return Err(()),
                }
                // navigate to current table then assign dotted keys
                let table = navigate_current(&mut root, &current_path)?;
                assign_dotted(table, &keys, value)?;
            }
        }
    }

    fn parse_dotted_key(&mut self) -> Result<Vec<String>, ()> {
        let mut keys = Vec::new();
        loop {
            self.skip_ws_inline();
            let key = self.parse_key()?;
            keys.push(key);
            self.skip_ws_inline();
            if self.peek() == Some('.') {
                self.bump();
                continue;
            }
            break;
        }
        Ok(keys)
    }

    fn parse_key(&mut self) -> Result<String, ()> {
        match self.peek() {
            Some('"') => {
                let v = self.parse_basic_string(false)?;
                Ok(v)
            }
            Some('\'') => {
                let v = self.parse_literal_string(false)?;
                Ok(v)
            }
            _ => {
                let start = self.pos;
                while let Some(c) = self.peek() {
                    if c.is_ascii_alphanumeric() || c == '_' || c == '-' {
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
                if self.pos == start {
                    return Err(());
                }
                Ok(self.chars[start..self.pos].iter().collect())
            }
        }
    }

    fn parse_value(&mut self) -> Result<Value, ()> {
        self.skip_ws_inline();
        match self.peek() {
            Some('"') => Ok(Value::Str(self.parse_basic_string(true)?)),
            Some('\'') => Ok(Value::Str(self.parse_literal_string(true)?)),
            Some('[') => {
                self.bump();
                let mut items = Vec::new();
                loop {
                    self.skip_ws_and_comments();
                    if self.peek() == Some(']') {
                        self.bump();
                        break;
                    }
                    let item = self.parse_value()?;
                    items.push(item);
                    self.skip_ws_and_comments();
                    if self.peek() == Some(',') {
                        self.bump();
                        continue;
                    }
                    if self.peek() == Some(']') {
                        self.bump();
                        break;
                    }
                    return Err(());
                }
                Ok(Value::Array(items))
            }
            Some('{') => {
                self.bump();
                let mut table: Vec<(String, Value)> = Vec::new();
                loop {
                    // TOML inline tables are normally single-line, but be permissive.
                    self.skip_ws_inline();
                    if self.peek() == Some('}') {
                        self.bump();
                        break;
                    }
                    let keys = self.parse_dotted_key()?;
                    self.skip_ws_inline();
                    self.expect_char('=')?;
                    self.skip_ws_inline();
                    let value = self.parse_value()?;
                    assign_dotted_table(&mut table, &keys, value)?;
                    self.skip_ws_inline();
                    if self.peek() == Some(',') {
                        self.bump();
                        continue;
                    }
                    if self.peek() == Some('}') {
                        self.bump();
                        break;
                    }
                    return Err(());
                }
                Ok(Value::Table(table))
            }
            _ => {
                // Raw token
                let start = self.pos;
                while let Some(c) = self.peek() {
                    if c == ',' || c == ']' || c == '}' || c == '#' || c == '\n' || c == '\r' {
                        break;
                    }
                    self.pos += 1;
                }
                let token: String = self.chars[start..self.pos].iter().collect::<String>().trim().to_string();
                if token.is_empty() || token.contains(' ') || token.contains('\t') || token.contains('[') || token.contains('{') {
                    return Err(());
                }
                if token == "true" {
                    Ok(Value::Bool(true))
                } else if token == "false" {
                    Ok(Value::Bool(false))
                } else {
                    Ok(Value::Raw(token))
                }
            }
        }
    }

    fn parse_basic_string(&mut self, allow_multiline: bool) -> Result<String, ()> {
        // assumes current char is "
        if allow_multiline && self.starts_with("\"\"\"") {
            self.pos += 3;
            // first newline trimmed
            if self.starts_with("\r\n") {
                self.pos += 2;
            } else if self.peek() == Some('\n') {
                self.pos += 1;
            }
            let mut out = String::new();
            loop {
                if self.pos >= self.chars.len() {
                    return Err(());
                }
                if self.starts_with("\"\"\"") {
                    // Up to two additional quotes may be content immediately before delimiter.
                    // Our generator escapes quotes, so treat first """ as end.
                    self.pos += 3;
                    break;
                }
                let c = self.bump().ok_or(())?;
                if c == '\\' {
                    // line-ending backslash
                    let save = self.pos;
                    let mut idx = self.pos;
                    while matches!(self.chars.get(idx), Some(' ') | Some('\t')) {
                        idx += 1;
                    }
                    if matches!(self.chars.get(idx), Some('\n')) || (matches!(self.chars.get(idx), Some('\r')) && matches!(self.chars.get(idx + 1), Some('\n'))) {
                        // skip whitespace and newlines
                        self.pos = idx;
                        self.skip_ws_and_comments_basic_ml();
                        continue;
                    }
                    self.pos = save;
                    let e = self.parse_escape()?;
                    out.push(e);
                } else {
                    out.push(c);
                }
            }
            return Ok(out);
        }
        self.expect_char('"')?;
        let mut out = String::new();
        loop {
            let c = self.bump().ok_or(())?;
            match c {
                '"' => break,
                '\n' | '\r' => return Err(()),
                '\\' => {
                    let e = self.parse_escape()?;
                    out.push(e);
                }
                _ => out.push(c),
            }
        }
        Ok(out)
    }

    fn skip_ws_and_comments_basic_ml(&mut self) {
        loop {
            while matches!(self.peek(), Some(' ') | Some('\t') | Some('\n') | Some('\r')) {
                self.pos += 1;
            }
            // comments are not special inside strings
            break;
        }
    }

    fn parse_escape(&mut self) -> Result<char, ()> {
        let c = self.bump().ok_or(())?;
        match c {
            'b' => Ok('\u{8}'),
            't' => Ok('\t'),
            'n' => Ok('\n'),
            'f' => Ok('\u{c}'),
            'r' => Ok('\r'),
            '"' => Ok('"'),
            '\\' => Ok('\\'),
            '/' => Ok('/'),
            'u' => {
                let mut v = 0u32;
                for _ in 0..4 {
                    let h = self.bump().ok_or(())?;
                    v = v * 16 + h.to_digit(16).ok_or(())?;
                }
                char::from_u32(v).ok_or(())
            }
            'U' => {
                let mut v = 0u32;
                for _ in 0..8 {
                    let h = self.bump().ok_or(())?;
                    v = v * 16 + h.to_digit(16).ok_or(())?;
                }
                char::from_u32(v).ok_or(())
            }
            _ => Err(()),
        }
    }

    fn parse_literal_string(&mut self, allow_multiline: bool) -> Result<String, ()> {
        if allow_multiline && self.starts_with("'''") {
            self.pos += 3;
            if self.starts_with("\r\n") {
                self.pos += 2;
            } else if self.peek() == Some('\n') {
                self.pos += 1;
            }
            let mut out = String::new();
            loop {
                if self.pos >= self.chars.len() {
                    return Err(());
                }
                if self.starts_with("'''") {
                    self.pos += 3;
                    break;
                }
                out.push(self.bump().ok_or(())?);
            }
            return Ok(out);
        }
        self.expect_char('\'')?;
        let mut out = String::new();
        loop {
            let c = self.bump().ok_or(())?;
            match c {
                '\'' => break,
                '\n' | '\r' => return Err(()),
                _ => out.push(c),
            }
        }
        Ok(out)
    }
}

fn table_mut(v: &mut Value) -> Result<&mut Vec<(String, Value)>, ()> {
    match v {
        Value::Table(t) => Ok(t),
        _ => Err(()),
    }
}

fn ensure_table(root: &mut Value, keys: &[String]) -> Result<(), ()> {
    let mut cur = root;
    for k in keys {
        let t = table_mut(cur)?;
        if let Some((_, existing)) = t.iter_mut().find(|(ek, _)| ek == k) {
            match existing {
                Value::Table(_) => {
                    cur = existing;
                }
                _ => return Err(()),
            }
        } else {
            t.push((k.clone(), Value::Table(Vec::new())));
            let idx = t.len() - 1;
            cur = &mut t[idx].1;
        }
    }
    Ok(())
}

fn append_array_table(root: &mut Value, keys: &[String]) -> Result<(), ()> {
    if keys.is_empty() {
        return Err(());
    }
    // navigate to parent
    let mut cur = root;
    for k in &keys[..keys.len() - 1] {
        let t = table_mut(cur)?;
        if let Some((_, existing)) = t.iter_mut().find(|(ek, _)| ek == k) {
            cur = existing;
            // if cur is an array (array of tables), descend into last
            if let Value::Array(arr) = cur {
                if arr.is_empty() {
                    return Err(());
                }
                let last = arr.len() - 1;
                cur = &mut arr[last];
            }
        } else {
            t.push((k.clone(), Value::Table(Vec::new())));
            let idx = t.len() - 1;
            cur = &mut t[idx].1;
        }
    }
    let last_key = &keys[keys.len() - 1];
    let t = table_mut(cur)?;
    if let Some((_, existing)) = t.iter_mut().find(|(ek, _)| ek == last_key) {
        match existing {
            Value::Array(arr) => {
                arr.push(Value::Table(Vec::new()));
                Ok(())
            }
            _ => Err(()),
        }
    } else {
        t.push((last_key.clone(), Value::Array(vec![Value::Table(Vec::new())])));
        Ok(())
    }
}

fn navigate_current<'a>(root: &'a mut Value, current_path: &[String]) -> Result<&'a mut Vec<(String, Value)>, ()> {
    if current_path.is_empty() {
        return table_mut(root);
    }
    let is_array = current_path.get(0).map(|s| s.as_str()) == Some("\u{1}ARRAY");
    let keys: &[String] = if is_array { &current_path[1..] } else { current_path };
    let mut cur = root;
    for k in keys {
        let t = table_mut(cur)?;
        let (_, existing) = t.iter_mut().find(|(ek, _)| ek == k).ok_or(())?;
        cur = existing;
        if let Value::Array(arr) = cur {
            if arr.is_empty() {
                return Err(());
            }
            let last = arr.len() - 1;
            cur = &mut arr[last];
        }
    }
    table_mut(cur)
}

fn assign_dotted_table(table: &mut Vec<(String, Value)>, keys: &[String], value: Value) -> Result<(), ()> {
    if keys.is_empty() {
        return Err(());
    }
    if keys.len() == 1 {
        if table.iter().any(|(k, _)| k == &keys[0]) {
            return Err(());
        }
        table.push((keys[0].clone(), value));
        return Ok(());
    }
    // intermediate
    let first = &keys[0];
    if let Some((_, existing)) = table.iter_mut().find(|(k, _)| k == first) {
        match existing {
            Value::Table(inner) => assign_dotted_table(inner, &keys[1..], value),
            _ => Err(()),
        }
    } else {
        table.push((first.clone(), Value::Table(Vec::new())));
        let idx = table.len() - 1;
        match &mut table[idx].1 {
            Value::Table(inner) => assign_dotted_table(inner, &keys[1..], value),
            _ => Err(()),
        }
    }
}

fn assign_dotted(table: &mut Vec<(String, Value)>, keys: &[String], value: Value) -> Result<(), ()> {
    assign_dotted_table(table, keys, value)
}

// ---------- Serialization ----------

fn basic_escape_single(s: &str) -> String {
    let mut out = String::new();
    for ch in s.chars() {
        match ch {
            '\u{8}' => out.push_str("\\b"),
            '\t' => out.push_str("\\t"),
            '\n' => out.push_str("\\n"),
            '\u{c}' => out.push_str("\\f"),
            '\r' => out.push_str("\\r"),
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            c if (c as u32) < 0x20 || ((c as u32) >= 0x7f && (c as u32) <= 0x9f) => {
                out.push_str(&format!("\\u{:04X}", c as u32));
            }
            c => out.push(c),
        }
    }
    out
}

fn basic_escape_multiline(s: &str) -> String {
    let mut out = String::new();
    for ch in s.chars() {
        match ch {
            '\u{8}' => out.push_str("\\b"),
            '\t' => out.push_str("\\t"),
            '\n' => out.push('\n'),
            '\u{c}' => out.push_str("\\f"),
            '\r' => out.push_str("\\r"),
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            c if (c as u32) < 0x20 || ((c as u32) >= 0x7f && (c as u32) <= 0x9f) => {
                out.push_str(&format!("\\u{:04X}", c as u32));
            }
            c => out.push(c),
        }
    }
    out
}

fn needs_basic(s: &str) -> bool {
    s.chars().any(|c| {
        let v = c as u32;
        (v < 0x20 && c != '\t' && c != '\n') || (v >= 0x7f && v <= 0x9f)
    })
}

pub fn string_repr(s: &str) -> String {
    if s.contains('\n') {
        if needs_basic(s) || s.contains("'''") {
            format!("\"\"\"\n{}\"\"\"", basic_escape_multiline(s))
        } else {
            // Multiline literal; if content ends with a single quote, fall back to basic
            // to avoid delimiter ambiguity (matches observed behaviour for trailing quotes).
            if s.ends_with('\'') {
                format!("\"\"\"\n{}\"\"\"", basic_escape_multiline(s))
            } else {
                format!("'''\n{}'''", s)
            }
        }
    } else if needs_basic(s) {
        format!("\"{}\"", basic_escape_single(s))
    } else if !s.contains('\'') {
        format!("'{}'", s)
    } else if s.ends_with('\'') || s.contains("'''") {
        format!("\"{}\"", basic_escape_single(s))
    } else {
        format!("'''{}'''", s)
    }
}

pub fn key_repr(s: &str) -> String {
    if !s.is_empty() && s.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-') {
        s.to_string()
    } else {
        format!("\"{}\"", basic_escape_single(s))
    }
}
