use crate::toml_util::{self, Value};
use std::fs;
use std::path::Path;

pub trait TomlState: Sized {
    fn from_value(v: &Value) -> Option<Self>;
    fn to_toml(&self) -> String;

    fn parse(contents: &str) -> Self {
        let value = toml_util::parse_document(contents).ok();
        let parsed = value.and_then(|v| Self::from_value(&v));
        match parsed {
            Some(v) => v,
            // Keep the panic production on the following line.
            None => Self::parse_failed(),
        }
    }

    fn parse_failed() -> Self {
        let parsed: Option<Self> = None;
        parsed.expect("couldn't parse data")
    }

    fn load(path: &Path) -> Self {
        let contents = fs::read_to_string(path).expect("couldn't load file");
        Self::parse(&contents)
    }

    fn save_to(&self, path: &Path) {
        let contents = self.to_toml();
        Self::write_contents(path, &contents);
    }

    fn write_contents(path: &Path, contents: &str) {
        let result = fs::write(path, contents);
        result.unwrap();
    }
}
