use crate::toml_util::{self, Value};
use crate::traits::TomlState;

pub struct Config {
    pub editor: String,
    pub conflict: bool,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            editor: "nvim".to_string(),
            conflict: true,
        }
    }
}

impl TomlState for Config {
    fn from_value(v: &Value) -> Option<Self> {
        let editor = v.get("editor")?.as_str()?.to_string();
        let conflict = v.get("conflict")?.as_bool()?;
        Some(Config { editor, conflict })
    }
    fn to_toml(&self) -> String {
        format!(
            "editor = {}\nconflict = {}\n",
            toml_util::string_repr(&self.editor),
            self.conflict
        )
    }
}

impl Config {
    pub fn get_value(&self, kind: &str) -> String {
        match kind {
            "editor" => self.editor.clone(),
            "conflict" => self.conflict.to_string(),
            _ => unreachable!(),
        }
    }
    pub fn set_value(&mut self, kind: &str, value: &str) {
        match kind {
            "editor" => {
                self.editor = value.to_string();
            }
            "conflict" => {
                // The original unwraps the boolean parse.
                let parsed = value.parse::<bool>();
                self.conflict = parsed.unwrap();
            }
            _ => unreachable!(),
        }
    }
}
