use crate::errors::{err, undefined_error, AppResult};
use std::fs;
use std::path::{Path, PathBuf};

pub fn is_valid_name(name: &str) -> bool {
    !name.chars().any(|c| {
        matches!(
            c,
            '"' | '%' | '*' | '/' | ':' | '<' | '>' | '?' | '\\' | '|'
        )
    })
}

pub fn require_valid_name(name: &str) -> AppResult<()> {
