    }
}

/// Resolve a user supplied path for chdir / move (note & folder).
/// Returns (canonical_destination).
pub fn resolve_destination(
    current_path: &Path,
    vault_path: &Path,
    destination: &str,
) -> AppResult<PathBuf> {
