    let canonical = match joined.canonicalize() {
        Ok(p) => p,
        Err(_) => return err("couldn't find the path specified"),
    };
    if canonical == current_path {
        return err("new location is same as old location");
    }
    if !canonical.starts_with(vault_path) {
        return err("path crosses the bounds of vault");
    }
    Ok(canonical)
}

pub fn note_path(current_path: &Path, name: &str) -> PathBuf {
    let mut path = current_path.join(name);
    path.set_extension("md");
