/// Move an item (file or directory) to an explicit destination.
/// `dest_dir` is the folder that will contain the item and
/// `dest_item` is dest_dir joined with the item's file name.
pub fn move_item_to(source: &Path, dest_dir: &Path, dest_item: &Path) -> Result<(), String> {
    if source.is_dir() {
        copy_dir_recursive(source, dest_dir)?;
        match fs::remove_dir_all(source) {
            Ok(()) => Ok(()),
            Err(io) => Err(move_error_from_io(io)),
