                return Err(move_error_from_io(io));
            }
        }
        if let Err(io) = fs::copy(source, dest_item) {
            return Err(move_error_from_io(io));
        }
        if let Err(io) = fs::remove_file(source) {
            return Err(move_error_from_io(io));
        }
        Ok(())
    }
}

pub fn remove_file_mapped(path: &Path, not_found_msg: String) -> AppResult<()> {
    match fs::remove_file(path) {
        Ok(()) => Ok(()),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Err(not_found_msg),
        Err(e) => err(undefined_error(&e)),
    }
}

pub fn remove_dir_mapped(path: &Path, not_found_msg: String) -> AppResult<()> {
    match fs::remove_dir_all(path) {
