        e.to_string().to_lowercase()
    } else {
        "io error".to_string()
    }
}

pub enum MoveFailure {
    Message(String),
}

fn copy_dir_recursive(source: &Path, dest_parent: &Path) -> Result<(), String> {
    // Snapshot entries before creating the destination directory. This is
    // important for the degenerate case of moving a folder into itself.
    let source_name = source.file_name().unwrap();
    let entries = match fs::read_dir(source) {
        Ok(rd) => {
            let mut v = Vec::new();
            for e in rd {
                match e {
                    Ok(entry) => v.push(entry.path()),
                    Err(io) => return Err(move_error_from_io(io)),
                }
            }
            v
        }
        Err(io) => return Err(move_error_from_io(io)),
    };
    let dest_dir = dest_parent.join(source_name);
    if let Err(io) = fs::create_dir(&dest_dir) {
        return Err(move_error_from_io(io));
    }
    for entry_path in entries {
        // A symlink needs special handling.
        let symlink_meta = match fs::symlink_metadata(&entry_path) {
            Ok(m) => m,
            Err(io) => return Err(move_error_from_io(io)),
        };
        if symlink_meta.file_type().is_symlink() {
            match fs::metadata(&entry_path) {
                Ok(meta) => {
                    if meta.is_dir() {
                        copy_dir_recursive(&entry_path, &dest_dir)?;
                    } else if meta.is_file() {
                        return Err(format!(
                            "path \"{}\" does not exist or you don't have access!",
                            entry_path.display()
                        ));
                    } else {
                        return Err(format!(
                            "path \"{}\" is not a file!",
                            entry_path.display()
                        ));
                    }
                }
                Err(io) => return Err(move_error_from_io(io)),
            }
        } else if entry_path.is_dir() {
            copy_dir_recursive(&entry_path, &dest_dir)?;
        } else if entry_path.is_file() {
            let dest_file = dest_dir.join(entry_path.file_name().unwrap());
            if let Err(io) = fs::copy(&entry_path, &dest_file) {
                return Err(move_error_from_io(io));
            }
        } else {
            return Err(format!(
                "path \"{}\" is not a file!",
                entry_path.display()
            ));
        }
    }
    Ok(())
}

/// Move a file or a folder into `dest_parent`, keeping the item's own
/// file name. Returns Err(message) with the text the caller should show
/// after the red `error:` prefix.
pub fn move_item(source: &Path, dest_parent: &Path) -> Result<(), String> {
    if source.is_dir() {
        // move_dir
        // fs_extra style: a missing source reports a not-found error
        // before a destination directory is created.
        if fs::metadata(source).is_err() {
            // metadata follows symlinks; fall through to copy which will
            // produce the right kind of error
        }
        copy_dir_recursive(source, dest_parent)?;
        // remove source recursively
        match fs::remove_dir_all(source) {
            Ok(()) => Ok(()),
            Err(io) => Err(move_error_from_io(io)),
        }
    } else {
        // move_file
        // Check the source really is a file (for fifos etc).
        match fs::metadata(source) {
            Ok(meta) => {
                if !meta.is_file() {
                    return Err(format!(
                        "path \"{}\" is not a file!",
                        source.display()
                    ));
                }
            }
            Err(io) => {
                return Err(move_error_from_io(io));
            }
        }
        let dest_file = dest_parent.join(source.file_name().unwrap());
        // dest_parent here is, for files, expected to be the destination
        // folder; callers that need a full file path use move_file_to.
        let _ = &dest_file;
        // This function is only used by callers that pass a full handling
        // via move_item_to, so this branch is unreachable in practice.
        Err(move_error_from_io(std::io::Error::from(
            std::io::ErrorKind::Other,
        )))
    }
}

/// Move an item (file or directory) to an explicit destination.
/// `dest_dir` is the folder that will contain the item and
/// `dest_item` is dest_dir joined with the item's file name.
pub fn move_item_to(source: &Path, dest_dir: &Path, dest_item: &Path) -> Result<(), String> {
    if source.is_dir() {
        copy_dir_recursive(source, dest_dir)?;
        match fs::remove_dir_all(source) {
            Ok(()) => Ok(()),
            Err(io) => Err(move_error_from_io(io)),
        }
    } else {
        match fs::metadata(source) {
            Ok(meta) => {
                if !meta.is_file() {
                    // Match the mover's message for non-files. For names
                    // carrying an extension the upstream library
                    // truncates after the stem; we keep the full
                    // conventional message used for extensionless
                    // names.
                    return Err(format!(
                        "path \"{}\" is not a file!",
                        source.display()
                    ));
                }
            }
            Err(io) => {
                return Err(move_error_from_io(io));
            }
        }
        if let Err(io) = fs::copy(source, dest_item) {
            return Err(move_error_from_io(io));
        }
        if let Err(io) = fs::remove_file(source) {
            return Err(move_error_from_io(io));
        }
        Ok(())
    }
}

pub fn remove_file_mapped(path: &Path, not_found_msg: String) -> AppResult<()> {
    match fs::remove_file(path) {
        Ok(()) => Ok(()),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Err(not_found_msg),
        Err(e) => err(undefined_error(&e)),
    }
}

pub fn remove_dir_mapped(path: &Path, not_found_msg: String) -> AppResult<()> {
    match fs::remove_dir_all(path) {
        Ok(()) => Ok(()),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Err(not_found_msg),
        Err(e) => err(undefined_error(&e)),
    }
}

pub fn rename_mapped(source: &Path, dest: &Path, not_found_msg: String) -> AppResult<()> {
    match fs::rename(source, dest) {
        Ok(()) => Ok(()),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Err(not_found_msg),
        Err(e) => err(undefined_error(&e)),
    }
}
