pub fn bin_name() -> String {
    if let Some(arg0) = std::env::args_os().next() {
        let path = std::path::Path::new(&arg0);
        if let Some(name) = path.file_name() {
            let s = name.to_string_lossy().to_string();
            if !s.is_empty() {
                return s;
            }
