struct Spec {
    canonical: &'static str,
    alias: &'static str,
    about: &'static str,
}

const SPECS: &[Spec] = &[
    Spec { canonical: "vault", alias: "vl", about: "create a vault or list vaults" },
    Spec { canonical: "note", alias: "nt", about: "create a note" },
    Spec { canonical: "folder", alias: "fd", about: "create a folder" },
    Spec { canonical: "enter", alias: "en", about: "enter a vault" },
    Spec { canonical: "open", alias: "op", about: "open a note (from the current folder)" },
    Spec { canonical: "opdir", alias: "od", about: "open current folder in file explorer" },
    Spec { canonical: "chdir", alias: "cd", about: "change folder within current vault" },
    Spec { canonical: "list", alias: "ls", about: "list items in current folder" },
    Spec { canonical: "remove", alias: "rm", about: "remove an item" },
    Spec { canonical: "rename", alias: "rn", about: "rename an item" },
    Spec { canonical: "move", alias: "mv", about: "move an item to a new location" },
    Spec { canonical: "vmove", alias: "vm", about: "move notes and folders to a different vault" },
    Spec { canonical: "config", alias: "cf", about: "display, set or open config" },
];

fn find_spec(name: &str) -> Option<&'static Spec> {
    SPECS.iter().find(|s| s.canonical == name || s.alias == name)
}

fn usage_lines(bin: &str, canonical: &str) -> Vec<String> {
    match canonical {
        "vault" => vec![
            "jt vault".to_string(),
            "jt vault -l".to_string(),
            "jt vault <vault name> <vault location>".to_string(),
        ],
        "note" => vec!["jt note".to_string(), "jt note [note name]".to_string()],
        "folder" => vec!["jt folder".to_string(), "jt folder [folder name]".to_string()],
        "config" => vec![
            "jt config <config type>".to_string(),
            "jt config <config type> [config value]".to_string(),
        ],
        "enter" => vec![format!("{} enter <vault name>", bin)],
        "open" => vec![format!("{} open <note name>", bin)],
        "opdir" => vec![format!("{} opdir", bin)],
        "chdir" => vec![format!("{} chdir <folder path>", bin)],
        "list" => vec![format!("{} list [item type]", bin)],
        "remove" => vec![format!("{} remove <item type> <name>", bin)],
        "rename" => vec![format!("{} rename <item type> <name> <new name>", bin)],
        "move" => vec![format!("{} move <item type> <name> <new location>", bin)],
        "vmove" => vec![format!("{} vmove <item type> <name> <vault name>", bin)],
        "help" => vec![format!("{} help", bin)],
        _ => vec![format!("{} <SUBCOMMAND>", bin)],
    }
}

fn usage_block(bin: &str, canonical: &str) -> String {
    let lines = usage_lines(bin, canonical);
    let mut out = String::from("USAGE:\n");
    for line in &lines {
        out.push_str(&format!("    {}\n", line));
    }
    out
}

fn usage_block_for_error(bin: &str, canonical: &str) -> String {
    // USAGE block without trailing blank line; callers add separators.
    usage_block(bin, canonical)
}

fn args_help(canonical: &str) -> Option<String> {
    let body = match canonical {
        "vault" => "    <vault name>        name for new vault\n    <vault location>    absolute path to location of new vault\n",
        "note" => "    <note name>    name for new note (to be created in the current folder)\n",
        "folder" => "    <folder name>    name for new folder (to be created in the current folder)\n",
        "enter" => "    <vault name>    name of the vault to enter\n",
        "open" => "    <note name>    name of note to be opened\n",
        "chdir" => "    <folder path>    path to folder to switch to (from current folder)\n",
        "list" => "    <item type>    \n",
        "remove" => "    <item type>    remove a vault (or vl) | note (or nt) | folder (or fd)\n    <name>         name of item to be removed\n",
        "rename" => "    <item type>    rename a vault (or vl) | note (or nt) | folder (or fd)\n    <name>         name of item to be renamed\n    <new name>     new name of item\n",
        "move" => "    <item type>       move a vault (or vl) | note (or nt) | folder (or fd)\n    <name>            name of item to be moved\n    <new location>    path to new location of item (current folder as root in case of note or\n                      folder)\n",
        "vmove" => "    <item type>     move a note (or nt) | folder (or fd)\n    <name>          name of item to be moved\n    <vault name>    name of vault to move the item to\n",
        "config" => "    <config type>     name of config item to display or set\n    <config value>    pass a value if config needs to be updated\n",
        _ => return None,
    };
    Some(format!("ARGS:\n{}", body))
}

fn help_text(bin: &str, canonical: &str) -> String {
    if canonical == "help" {
        return format!(
            "{}-help \n🆘 show this help message or help for given command\n\nUSAGE:\n    {} help\n\nOPTIONS:\n    -h, --help    Print help information\n",
            bin, bin
        );
    }
    let spec = find_spec(canonical).unwrap();
    let mut out = String::new();
    out.push_str(&format!("{}-{} \n{}\n\n", bin, spec.canonical, spec.about));
    out.push_str(&usage_block(bin, canonical));
    out.push('\n');
    if let Some(args) = args_help(canonical) {
        out.push_str(&args);
        out.push('\n');
    }
    out.push_str("OPTIONS:\n");
    if canonical == "vault" {
        out.push_str("    -l            show vaults' location\n");
    }
    out.push_str("    -h, --help    Print help information\n");
    out
}

fn print_sub_help(bin: &str, canonical: &str) -> ! {
    print!("{}", help_text(bin, canonical));
    exit_with(0)
}

// ---------- suggestions (Jaro-Winkler, clap style) ----------

fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.is_empty() && b.is_empty() {
        return 1.0;
    }
    if a.is_empty() || b.is_empty() {
        return 0.0;
    }
    if a == b {
        return 1.0;
    }
    let search_range = (a.len().max(b.len()) / 2).saturating_sub(1);
    let mut b_consumed = vec![false; b.len()];
    let mut matches = 0usize;
    let mut transpositions = 0usize;
    let mut b_match_index = 0usize;
    // Standard Jaro implementation mirroring strsim.
    let mut a_matches = vec![false; a.len()];
    for i in 0..a.len() {
        let start = i.saturating_sub(search_range);
        let end = (i + search_range + 1).min(b.len());
        for j in start..end {
            if !b_consumed[j] && a[i] == b[j] {
                a_matches[i] = true;
                b_consumed[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut j = 0usize;
    for i in 0..a.len() {
        if a_matches[i] {
            while !b_consumed[j] {
                j += 1;
            }
            if a[i] != b[j] {
                transpositions += 1;
            }
            j += 1;
        }
    }
    let _ = b_match_index;
    let _ = &mut b_match_index;
    let m = matches as f64;
    ((m / a.len() as f64) + (m / b.len() as f64) + ((m - (transpositions / 2) as f64) / m)) / 3.0
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let j = jaro(a, b);
    if j > 0.7 {
        let prefix = a
            .chars()
            .zip(b.chars())
            .take_while(|(x, y)| x == y)
            .count()
            .min(4);
        j + (prefix as f64 * 0.1 * (1.0 - j))
    } else {
        j
    }
}

fn did_you_mean(v: &str, candidates: &[&str]) -> Vec<String> {
    let mut cand: Vec<(f64, String)> = candidates
        .iter()
        .map(|pv| (jaro_winkler(v, pv), pv.to_string()))
        .filter(|(conf, _)| *conf > 0.8)
        .collect();
    cand.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    cand.dedup_by(|a, b| a.1 == b.1);
    cand.into_iter().map(|(_, pv)| pv).collect()
}

fn subcommand_candidates() -> Vec<&'static str> {
    let mut v = Vec::new();
    for s in SPECS {
        v.push(s.canonical);
        v.push(s.alias);
    }
    v.push("help");
    v
}

// ---------- clap style errors (print to stderr, exit 2) ----------

fn error_exit(msg: String) -> ! {
    eprint!("{}", msg);
    exit_with(2)
}

fn err_unknown_argument(bin: &str, canonical: &str, disp: &str, flag_suggestion: Option<String>, supply_hint: bool) -> ! {
    let mut out = format!(
        "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n",
        disp
    );
    if let Some(sugg) = flag_suggestion {
        out.push_str(&format!("\n\tDid you mean '{}'?\n", sugg));
    }
    if supply_hint {
        out.push_str(&format!(
            "\n\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`\n",
            disp, disp
        ));
    }
    out.push_str(&format!(
        "\n{}\nFor more information try --help\n",
        usage_block_for_error(bin, canonical)
    ));
    error_exit(out)
}

fn err_unrecognized_subcommand(bin: &str, usage_canonical: &str, arg: &str, suggestions: Option<Vec<String>>, include_rerun_hint: bool) -> ! {
    let mut out = format!("error: The subcommand '{}' wasn't recognized\n", arg);
    if let Some(suggs) = suggestions {
        if !suggs.is_empty() {
            out.push_str("\n\tDid you mean ");
            if suggs.len() == 1 {
                out.push_str(&format!("'{}'?", suggs[0]));
            } else if suggs.len() == 2 {
                out.push_str(&format!("'{}' or '{}'?", suggs[0], suggs[1]));
            } else {
                // Join with commas and final or
                for (i, s) in suggs.iter().enumerate() {
                    if i == 0 {
                        out.push_str(&format!("'{}'", s));
                    } else if i == suggs.len() - 1 {
                        out.push_str(&format!(", or '{}'?", s));
                    } else {
                        out.push_str(&format!(", '{}'", s));
                    }
                }
                // The above adds ? only at end for len>2; for len==? handled
                if suggs.len() > 2 {
                    // already appended
                }
            }
            out.push_str("\n");
            if suggs.len() > 2 {
                // Fix: the generic branch already closed with ?
            }
        }
    }
    if include_rerun_hint {
        out.push_str(&format!(
            "\nIf you believe you received this message in error, try re-running with '{} -- {}'\n",
            bin, arg
        ));
    }
    out.push_str(&format!(
        "\n{}\nFor more information try --help\n",
        usage_block_for_error(bin, usage_canonical)
    ));
    error_exit(out)
}

fn err_missing(bin: &str, canonical: &str, missing: &[&str]) -> ! {
    let mut out = String::from("error: The following required arguments were not provided:\n");
    for m in missing {
        out.push_str(&format!("    {}\n", m));
    }
    out.push_str(&format!(
        "\n{}\nFor more information try --help\n",
        usage_block_for_error(bin, canonical)
    ));
    error_exit(out)
}

fn err_invalid_value(arg_display: &str, value: &str, possible: &[&str]) -> ! {
    let mut out = format!(
        "error: \"{}\" isn't a valid value for '{}'\n\t[possible values: {}]\n",
        value,
        arg_display,
        possible.join(", ")
    );
    let suggs = did_you_mean(value, possible);
    if let Some(best) = suggs.last() {
        out.push_str(&format!("\n\tDid you mean \"{}\"?\n", best));
    }
    out.push_str("\nFor more information try --help\n");
    error_exit(out)
}

fn err_requires_value(arg_display: &str) -> ! {
    error_exit(format!(
        "error: The argument '{}' requires a value but none was supplied\n\nFor more information try --help\n",
        arg_display
    ))
}

fn err_duplicate_l(bin: &str) -> ! {
    let mut out = String::from("error: The argument '-l' was provided more than once, but cannot be used multiple times\n");
    out.push_str(&format!(
        "\n{}\nFor more information try --help\n",
        usage_block_for_error(bin, "vault")
    ));
    error_exit(out)
}

fn err_help_value(bin: &str, canonical: &str, value: &str) -> ! {
    let lines = if canonical == "top" {
        vec![format!("{} <SUBCOMMAND>", bin)]
    } else {
        usage_lines(bin, canonical)
    };
    let mut usage = String::new();
    for (i, line) in lines.iter().enumerate() {
        if i == 0 {
            usage.push_str(&format!("{}\n", line));
        } else {
            usage.push_str(&format!("    {}\n", line));
        }
    }
    error_exit(format!(
        "error: The value '{}' was provided to '--help' but it wasn't expecting any more values\n\n{}\nFor more information try --help\n",
        value, usage
    ))
}

// ---------- argument definitions ----------

struct ArgDef {
    display: &'static str,
    possible: Option<&'static [&'static str]>,
    forbid_empty: bool,
}

fn arg_defs(canonical: &str) -> Vec<ArgDef> {
    const FULL: &[&str] = &["vault", "vl", "note", "nt", "folder", "fd"];
    const NOTE_FOLDER: &[&str] = &["note", "nt", "folder", "fd"];
    const CONFIGV: &[&str] = &["editor", "conflict"];
    match canonical {
        "vault" => vec![
            ArgDef { display: "<vault name>", possible: None, forbid_empty: false },
            ArgDef { display: "<vault location>", possible: None, forbid_empty: true },
        ],
        "note" => vec![ArgDef { display: "<note name>", possible: None, forbid_empty: false }],
        "folder" => vec![ArgDef { display: "<folder name>", possible: None, forbid_empty: false }],
        "enter" => vec![ArgDef { display: "<vault name>", possible: None, forbid_empty: false }],
        "open" => vec![ArgDef { display: "<note name>", possible: None, forbid_empty: false }],
        "opdir" => vec![],
        "chdir" => vec![ArgDef { display: "<folder path>", possible: None, forbid_empty: true }],
        "list" => vec![ArgDef { display: "<item type>", possible: Some(NOTE_FOLDER), forbid_empty: false }],
        "remove" => vec![
            ArgDef { display: "<item type>", possible: Some(FULL), forbid_empty: false },
            ArgDef { display: "<name>", possible: None, forbid_empty: false },
        ],
        "rename" => vec![
            ArgDef { display: "<item type>", possible: Some(FULL), forbid_empty: false },
            ArgDef { display: "<name>", possible: None, forbid_empty: false },
            ArgDef { display: "<new name>", possible: None, forbid_empty: false },
        ],
        "move" => vec![
            ArgDef { display: "<item type>", possible: Some(FULL), forbid_empty: false },
            ArgDef { display: "<name>", possible: None, forbid_empty: false },
            ArgDef { display: "<new location>", possible: None, forbid_empty: true },
        ],
        "vmove" => vec![
            ArgDef { display: "<item type>", possible: Some(NOTE_FOLDER), forbid_empty: false },
            ArgDef { display: "<name>", possible: None, forbid_empty: false },
            ArgDef { display: "<vault name>", possible: None, forbid_empty: false },
        ],
        "config" => vec![
            ArgDef { display: "<config type>", possible: Some(CONFIGV), forbid_empty: false },
            ArgDef { display: "<config value>", possible: None, forbid_empty: false },
        ],
        _ => vec![],
    }
}

fn flag_suggestion(bin_canonical: &str, long_name: &str) -> Option<String> {
    let _ = bin_canonical;
    let suggs = did_you_mean(long_name, &["help"]);
    if let Some(best) = suggs.last() {
        Some(format!("--{}", best))
    } else {
        None
    }
}

fn parse_subcommand(bin: &str, spec: &'static Spec, args: &[String]) -> Command {
    let canonical = spec.canonical;
    let defs = arg_defs(canonical);
    let mut positionals: Vec<String> = Vec::new();
    let mut locations = false;
    let mut l_count = 0usize;
    let mut after_dd = false;

    for token in args {
        if !after_dd {
            if token == "--" {
                after_dd = true;
                continue;
            }
            if token == "-h" || token == "--help" {
                print_sub_help(bin, canonical);
            }
            if let Some(rest) = token.strip_prefix("--help=") {
                err_help_value(bin, canonical, rest);
            }
            if token.starts_with("--") {
                let disp = token.split('=').next().unwrap().to_string();
                let long_name = disp.trim_start_matches('-');
                let sugg = flag_suggestion(canonical, long_name);
                err_unknown_argument(bin, canonical, &disp, sugg, true);
            }
            if token.starts_with('-') && token != "-" {
                // short cluster
                for ch in token[1..].chars() {
                    if ch == 'h' {
                        print_sub_help(bin, canonical);
                    } else if canonical == "vault" && ch == 'l' {
                        l_count += 1;
                        locations = true;
                    } else {
                        let disp = format!("-{}", ch);
                        err_unknown_argument(bin, canonical, &disp, None, true);
                    }
                }
                continue;
            }
        }
        // positional
        if positionals.len() >= defs.len() {
            err_unknown_argument(bin, canonical, token, None, false);
        }
        let def = &defs[positionals.len()];
        if def.forbid_empty && token.is_empty() {
            err_requires_value(def.display);
        }
        if let Some(possible) = def.possible {
            if !possible.contains(&token.as_str()) {
                err_invalid_value(def.display, token, possible);
            }
        }
        positionals.push(token.clone());
    }

    if l_count > 1 {
        err_duplicate_l(bin);
    }

    match canonical {
        "vault" => {
            if positionals.len() == 1 {
                err_missing(bin, canonical, &["<vault location>"]);
            }
            Command::Vault {
                locations,
                name: positionals.get(0).cloned(),
                location: positionals.get(1).cloned(),
            }
        }
        "note" => {
            if positionals.is_empty() {
                err_missing(bin, canonical, &["<note name>"]);
            }
            Command::Note { name: positionals[0].clone() }
        }
        "folder" => {
            if positionals.is_empty() {
                err_missing(bin, canonical, &["<folder name>"]);
            }
            Command::Folder { name: positionals[0].clone() }
        }
        "enter" => {
            if positionals.is_empty() {
                err_missing(bin, canonical, &["<vault name>"]);
            }
            Command::Enter { name: positionals[0].clone() }
        }
        "open" => {
            if positionals.is_empty() {
                err_missing(bin, canonical, &["<note name>"]);
            }
            Command::Open { name: positionals[0].clone() }
        }
        "opdir" => Command::Opdir,
        "chdir" => {
            if positionals.is_empty() {
                err_missing(bin, canonical, &["<folder path>"]);
            }
            Command::Chdir { path: positionals[0].clone() }
        }
        "list" => {
            let item = positionals.get(0).and_then(|v| ItemKind::from_value(v));
            Command::List { item }
        }
        "remove" => {
            if positionals.len() < 2 {
                let mut missing: Vec<&str> = Vec::new();
                if positionals.len() < 1 {
                    missing.push("<item type>");
                }
                if positionals.len() < 2 {
                    missing.push("<name>");
                }
                err_missing(bin, canonical, &missing);
            }
            Command::Remove {
                item: ItemKind::from_value(&positionals[0]).unwrap(),
                name: positionals[1].clone(),
            }
        }
        "rename" => {
            if positionals.len() < 3 {
                let all = ["<item type>", "<name>", "<new name>"];
                let missing: Vec<&str> = all[positionals.len()..].to_vec();
                err_missing(bin, canonical, &missing);
            }
            Command::Rename {
                item: ItemKind::from_value(&positionals[0]).unwrap(),
                name: positionals[1].clone(),
                new_name: positionals[2].clone(),
            }
        }
        "move" => {
            if positionals.len() < 3 {
                let all = ["<item type>", "<name>", "<new location>"];
                let missing: Vec<&str> = all[positionals.len()..].to_vec();
                err_missing(bin, canonical, &missing);
            }
            Command::Move {
                item: ItemKind::from_value(&positionals[0]).unwrap(),
                name: positionals[1].clone(),
                new_location: positionals[2].clone(),
            }
        }
        "vmove" => {
            if positionals.len() < 3 {
                let all = ["<item type>", "<name>", "<vault name>"];
                let missing: Vec<&str> = all[positionals.len()..].to_vec();
                err_missing(bin, canonical, &missing);
            }
            Command::Vmove {
                item: ItemKind::from_value(&positionals[0]).unwrap(),
                name: positionals[1].clone(),
                vault_name: positionals[2].clone(),
            }
        }
        "config" => {
            let kind = positionals.get(0).and_then(|v| match v.as_str() {
                "editor" => Some(ConfigKind::Editor),
                "conflict" => Some(ConfigKind::Conflict),
                _ => None,
            });
            Command::Config {
                kind,
                value: positionals.get(1).cloned(),
            }
        }
        _ => unreachable!(),
    }
}

fn handle_help_command(bin: &str, args: &[String]) -> ! {
    if args.is_empty() {
        print_main_help_stdout();
    }
    let target = &args[0];
    if target == "help" {
        if args.len() == 1 {
            print!("{}", help_text(bin, "help"));
            exit_with(0);
        } else {
            err_unrecognized_subcommand(bin, "help", &args[1], None, false);
        }
    }
    if let Some(spec) = find_spec(target) {
        if args.len() == 1 {
            print_sub_help(bin, spec.canonical);
        } else {
            err_unrecognized_subcommand(bin, spec.canonical, &args[1], None, false);
        }
    } else {
        // For help, usage canonical is "top" (represented by canonical lookup below)
        // We pass a pseudo canonical recognised by usage_lines fallback.
        err_unrecognized_subcommand(bin, "__top__", target, None, false);
    }
}

pub fn parse() -> Command {
    let bin = bin_name();
    let args: Vec<String> = std::env::args().skip(1).collect();
    if args.is_empty() {
        print_main_help_stderr();
    }
    let first = &args[0];

    if first == "help" {
        handle_help_command(&bin, &args[1..]);
    }
    if first == "--" {
        if args.len() == 1 {
            print_main_help_stderr();
        }
        let second = &args[1];
        if find_spec(second).is_some() || second == "help" {
            // Valid subcommand name supplied after --
            let mut out = format!(
                "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n",
                second
            );
            out.push_str(&format!(
                "\n\tIf you tried to supply `{}` as a subcommand, remove the '--' before it.\n",
                second
            ));
            out.push_str(&format!(
                "\n{}\nFor more information try --help\n",
                usage_block_for_error(&bin, "__top__")
            ));
            error_exit(out);
        }
        // Suggestions based on the token as a potential subcommand
        let cand_strings: Vec<&str> = subcommand_candidates();
        let suggs = did_you_mean(second, &cand_strings);
        if !suggs.is_empty() {
            err_unrecognized_subcommand(&bin, "__top__", second, Some(suggs), true);
        }
        if second.starts_with('-') {
            err_unknown_argument(&bin, "__top__", second, None, true);
        } else {
            let mut out = format!(
                "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n",
                second
            );
            out.push_str(&format!(
                "\n\tIf you tried to supply `{}` as a subcommand, remove the '--' before it.\n",
                second
            ));
            out.push_str(&format!(
                "\n{}\nFor more information try --help\n",
                usage_block_for_error(&bin, "__top__")
            ));
            error_exit(out);
        }
    }
    if first == "-h" || first == "--help" {
        print_main_help_stdout();
    }
    if let Some(rest) = first.strip_prefix("--help=") {
        err_help_value(&bin, "top", rest);
    }
    if first.starts_with("--") {
        let disp = first.split('=').next().unwrap().to_string();
        let long_name = disp.trim_start_matches('-');
        let sugg = flag_suggestion("top", long_name);
        err_unknown_argument(&bin, "__top__", &disp, sugg, true);
    }
    if first.starts_with('-') && first != "-" {
        for ch in first[1..].chars() {
            if ch == 'h' {
                print_main_help_stdout();
            } else {
                let disp = format!("-{}", ch);
                err_unknown_argument(&bin, "__top__", &disp, None, true);
            }
        }
        // A token like "-" handled below; other clusters without h have exited.
        print_main_help_stderr();
    }
    if let Some(spec) = find_spec(first) {
        return parse_subcommand(&bin, spec, &args[1..]);
    }
    // Unknown first argument
    if first == "-" {
        err_unknown_argument(&bin, "__top__", first, None, true);
    }
    let cand_strings: Vec<&str> = subcommand_candidates();
    let suggs = did_you_mean(first, &cand_strings);
    if !suggs.is_empty() {
        err_unrecognized_subcommand(&bin, "__top__", first, Some(suggs), true);
    }
    err_unknown_argument(&bin, "__top__", first, None, false)
}
