fn require_vault_mut<'a>(state: &'a mut State) -> AppResult<&'a mut Vault> {
    if state.vaults.current.is_none() {
        return err("not inside a vault");
    }
    Ok(state.vault.as_mut().unwrap())
}

// ---------------- Vault command ----------------

fn vault_command(
    state: &mut State,
    locations: bool,
    name: Option<String>,
    location: Option<String>,
) -> AppResult<()> {
    let Some(name) = name else {
        // List vaults. Listing first resolves the current vault location
        // through the same lookup the state loader used; a stale current
        // entry panics there already.
        for (vname, vloc) in &state.vaults.vaults {
            let is_current = state.vaults.current.as_deref() == Some(vname.as_str());
            if locations {
                if is_current {
                    println!("👉 {} \t {}", blue(vname), vloc);
                } else {
                    println!("   {} \t {}", vname, vloc);
                }
            } else {
                if is_current {
                    println!("👉 {}", blue(vname));
                } else {
                    println!("   {}", vname);
                }
            }
        }
        return Ok(());
    };
    let location = location.unwrap();

    if state.vaults.vaults.contains_key(&name) {
        return err(format!("vault {} already exists", name));
    }
    let loc_path = Path::new(&location);
    if !loc_path.is_absolute() {
        return err("specified path isn't absolute");
    }
    let canonical_location = match loc_path.canonicalize() {
        Ok(p) => p,
        Err(_) => return err("couldn't find the path specified"),
    };
    utils::require_valid_name(&name)?;
    let vault_dir = canonical_location.join(&name);
    if vault_dir.exists() {
        return err(format!(
            "a folder named {} already exists in this location",
            name
        ));
    }
    if let Err(e) = fs::create_dir(&vault_dir) {
        return err(undefined_error(&e));
    }
    // Create .jot and its data file.
    let jot_dir = vault_dir.join(".jot");
    if let Err(e) = fs::create_dir(&jot_dir) {
        return err(undefined_error(&e));
    }
    let location_string = canonical_location.to_str().unwrap().to_string();
    let vault = Vault::new(&name, &location_string);
    // Save to the freshly created .jot/data path.
    let data_path = jot_dir.join("data");
    vault.save_to(&data_path);
    state
        .vaults
        .vaults
        .insert(name.clone(), location_string);
    state.save_vaults();
    println!("vault {} created", blue(&name));
    Ok(())
}

// ---------------- Enter ----------------

fn enter_vault(state: &mut State, name: &str) -> AppResult<()> {
    if !state.vaults.vaults.contains_key(name) {
        return err(format!("vault {} doesn't exist", name));
    }
    if state.vaults.current.as_deref() == Some(name) {
        return err(format!("already in vault {}", name));
    }
    state.vaults.current = Some(name.to_string());
    state.save_vaults();
    println!("entered {}", blue(name));
    Ok(())
}

// ---------------- Note / Folder creation ----------------

fn create_note(state: &mut State, name: &str) -> AppResult<()> {
    let vault = require_vault(state)?;
    utils::require_valid_name(name)?;
    let current_path = vault.current_path();
    if !current_path.exists() {
        return err("couldn't find the path specified");
    }
    let note_path = utils::note_path(&current_path, name);
    if note_path.exists() {
        return err(format!(
            "a note named {} already exists in this location",
            name
        ));
    }
    if let Err(e) = fs::File::create(&note_path) {
        return err(undefined_error(&e));
    }
    println!("note {} created", blue(name));
    Ok(())
}

fn create_folder(state: &mut State, name: &str) -> AppResult<()> {
    let vault = require_vault(state)?;
    utils::require_valid_name(name)?;
    let current_path = vault.current_path();
    if !current_path.exists() {
        return err("couldn't find the path specified");
    }
    let folder_path = current_path.join(name);
    if folder_path.exists() {
        return err(format!(
            "a folder named {} already exists in this location",
            name
        ));
    }
    if let Err(e) = fs::create_dir(&folder_path) {
        return err(undefined_error(&e));
    }
    println!("folder {} created", blue(name));
    Ok(())
}

// ---------------- Open / Opdir ----------------

fn open_with_editor(editor: &str, path: &Path) -> AppResult<()> {
    match ProcCommand::new(editor).arg(path).status() {
        Ok(_) => Ok(()),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => err("editor not found"),
        Err(e) => err(undefined_error(&e)),
    }
}

fn open_note(state: &mut State, name: &str) -> AppResult<()> {
    let vault = require_vault(state)?;
    utils::require_valid_name(name)?;
    let current_path = vault.current_path();
    let note_path = utils::note_path(&current_path, name);
    if !note_path.exists() {
        return err(format!("note {} not found", name));
    }
    let editor = state.config.editor.clone();
    open_with_editor(&editor, &note_path)
}

fn opdir(state: &mut State) -> AppResult<()> {
    let vault = require_vault(state)?;
    let current_path = vault.current_path();
    match ProcCommand::new("xdg-open").arg(&current_path).status() {
        Ok(_) => Ok(()),
        Err(e) => err(undefined_error(&e)),
    }
}

// ---------------- Chdir ----------------

fn chdir(state: &mut State, arg: &str) -> AppResult<()> {
    let (new_folder, data_path_hint) = {
        let vault = require_vault(state)?;
        let current_path = vault.current_path();
        let vault_path = vault.path();
        let canonical = utils::resolve_destination(&current_path, &vault_path, arg)?;
        // Strip vault prefix from canonical destination.
        let rel = match canonical.strip_prefix(&vault_path) {
            Ok(p) => p.to_path_buf(),
            Err(_) => return err("path crosses the bounds of vault"),
        };
        let folder_string = rel.to_str().unwrap().to_string();
        (folder_string, vault.data_path())
    };
    let _ = data_path_hint;
    let vault = require_vault_mut(state)?;
    vault.folder = new_folder;
    vault.save();
    println!("folder changed");
    Ok(())
}

// ---------------- List ----------------

fn list_items(state: &mut State, item: Option<ItemKind>) -> AppResult<()> {
    let vault = require_vault(state)?;
    // header
    if vault.folder.is_empty() {
        println!("{}", vault.name());
    } else {
        println!("{} > {}", vault.name(), vault.folder);
    }
    let current_path = vault.current_path();
    match item {
        None => {
            utils::print_tree(&current_path);
        }
        Some(ItemKind::Note) => {
            let notes = utils::list_notes(&current_path);
            let len = notes.len();
            for (i, note) in notes.iter().enumerate() {
                let connector = if i + 1 == len { "└── " } else { "├── " };
                println!("{}{}", connector, blue(&utils::display_stem(note)));
            }
        }
        Some(ItemKind::Folder) => {
            let folders = utils::list_folders(&current_path);
            let len = folders.len();
            for (i, folder) in folders.iter().enumerate() {
                let connector = if i + 1 == len { "└── " } else { "├── " };
                println!("{}{}", connector, utils::display_stem(folder));
            }
        }
        Some(ItemKind::Vault) => unreachable!(),
    }
    Ok(())
}

// ---------------- Remove ----------------

fn remove_item(state: &mut State, item: ItemKind, name: &str) -> AppResult<()> {
    match item {
        ItemKind::Vault => {
            let Some(location) = state.vaults.vaults.get(name).cloned() else {
                return err(format!("vault {} doesn't exist", name));
            };
            let vault_dir = Path::new(&location).join(name);
            utils::remove_dir_mapped(&vault_dir, format!("folder {} not found", name))?;
            state.vaults.vaults.remove(name);
            if state.vaults.current.as_deref() == Some(name) {
                state.vaults.current = None;
            }
            state.save_vaults();
            println!("vault {} removed", blue(name));
            Ok(())
        }
        ItemKind::Note => {
            let vault = require_vault(state)?;
            utils::require_valid_name(name)?;
            let note_path = utils::note_path(&vault.current_path(), name);
            utils::remove_file_mapped(&note_path, format!("note {} not found", name))?;
            println!("note {} removed", blue(name));
            Ok(())
        }
        ItemKind::Folder => {
            let vault = require_vault(state)?;
            utils::require_valid_name(name)?;
            let folder_path = vault.current_path().join(name);
            utils::remove_dir_mapped(&folder_path, format!("folder {} not found", name))?;
            println!("folder {} removed", blue(name));
            Ok(())
        }
    }
}

// ---------------- Rename ----------------

fn load_vault_at(vault_dir: &Path) -> Option<Vault> {
    let data_path = vault_dir.join(".jot").join("data");
    match data_path.try_exists() {
        Ok(true) => Some(Vault::load(&data_path)),
        Ok(false) => None,
        Err(_) => Some(Vault::load(&data_path)),
    }
}

fn rename_item(
    state: &mut State,
    item: ItemKind,
    name: &str,
    new_name: &str,
) -> AppResult<()> {
    match item {
        ItemKind::Vault => {
            if state.vaults.vaults.contains_key(new_name) {
                return err(format!("vault {} already exists", new_name));
            }
            let Some(location) = state.vaults.vaults.get(name).cloned() else {
                return err(format!("vault {} doesn't exist", name));
            };
            utils::require_valid_name(name)?;
            utils::require_valid_name(new_name)?;
            let old_dir = Path::new(&location).join(name);
            let new_dir = Path::new(&location).join(new_name);
            utils::rename_mapped(&old_dir, &new_dir, format!("folder {} not found", name))?;
            // Load/update the moved vault's data.
            match load_vault_at(&new_dir) {
                Some(mut vault) => {
                    vault.name = Some(new_name.to_string());
                    // save via the vault object's own path (location field)
                    vault.save();
                }
                None => {
                    let vault = Vault::new(new_name, &location);
                    let jot_dir = new_dir.join(".jot");
                    let _ = fs::create_dir_all(&jot_dir);
                    let data_path = jot_dir.join("data");
                    vault.save_to(&data_path);
                }
            }
            state.vaults.vaults.remove(name);
            state.vaults.vaults.insert(new_name.to_string(), location);
            if state.vaults.current.as_deref() == Some(name) {
                state.vaults.current = Some(new_name.to_string());
                // If the current in-memory vault is this one, keep it in
                // sync so later operations in this process are sane.
                if let Some(cur) = &mut state.vault {
                    if cur.name.as_deref() == Some(name) {
                        cur.name = Some(new_name.to_string());
                    }
                }
            }
            state.save_vaults();
            println!(
                "vault {} renamed to {}",
                blue(name),
                blue(new_name)
            );
            Ok(())
        }
        ItemKind::Note => {
            let vault = require_vault(state)?;
            if name == new_name {
                return err("new name is same as old name");
            }
            utils::require_valid_name(name)?;
            utils::require_valid_name(new_name)?;
            let current_path = vault.current_path();
            let source = utils::note_path(&current_path, name);
            let dest = utils::note_path(&current_path, new_name);
            utils::rename_mapped(&source, &dest, format!("note {} not found", name))?;
            println!("note {} renamed to {}", blue(name), blue(new_name));
            Ok(())
        }
        ItemKind::Folder => {
            let vault = require_vault(state)?;
            if name == new_name {
                return err("new name is same as old name");
            }
            utils::require_valid_name(name)?;
            utils::require_valid_name(new_name)?;
            let current_path = vault.current_path();
            let source = current_path.join(name);
            let dest = current_path.join(new_name);
            utils::rename_mapped(&source, &dest, format!("folder {} not found", name))?;
            println!("folder {} renamed to {}", blue(name), blue(new_name));
            Ok(())
        }
    }
}

// ---------------- Move ----------------

fn move_command(
    state: &mut State,
    item: ItemKind,
    name: &str,
    new_location: &str,
) -> AppResult<()> {
    match item {
        ItemKind::Vault => move_vault(state, name, new_location),
        ItemKind::Note | ItemKind::Folder => {
            let vault = require_vault(state)?;
            let current_path = vault.current_path();
            let vault_path = vault.path();
            let dest_dir = utils::resolve_destination(&current_path, &vault_path, new_location)?;
            utils::require_valid_name(name)?;
            // source / dest item
            let (source, dest_item) = match item {
                ItemKind::Note => {
                    let src = utils::note_path(&current_path, name);
                    let dst_name = src.file_name().unwrap().to_os_str().to_str().unwrap().to_string();
                    (src, dest_dir.join(dst_name))
                }
                _ => {
                    let src = current_path.join(name);
                    (src, dest_dir.join(name))
                }
            };
            if dest_item.exists() {
                return err(format!(
                    "a {} named {} already exists in this location",
                    item.word(),
                    name
                ));
            }
            utils::move_item_to(&source, &dest_dir, &dest_item)?;
            println!("{} {} moved", item.word(), blue(name));
            Ok(())
        }
    }
}

fn move_vault(state: &mut State, name: &str, new_location: &str) -> AppResult<()> {
    let dest_path = Path::new(new_location);
    if !dest_path.is_absolute() {
        return err("specified path isn't absolute");
    }
    let Some(location) = state.vaults.vaults.get(name).cloned() else {
        return err(format!("vault {} doesn't exist", name));
    };
    if dest_path == Path::new(&location) {
        return err("new location is same as old location");
    }
    let dest_item = dest_path.join(name);
    if dest_item.exists() {
        return err(format!(
            "a folder named {} already exists in this location",
            name
        ));
    }
    let source = Path::new(&location).join(name);
    utils::move_item_to(&source, dest_path, &dest_item)?;
    // Canonical new vault path determines the stored location.
    let canonical_item = dest_item.canonicalize().unwrap();
    let new_location_string = canonical_item
        .parent()
        .unwrap()
        .to_str()
        .unwrap()
        .to_string();
    let canonical_name = canonical_item
        .file_name()
        .unwrap()
        .to_str()
        .unwrap()
        .to_string();
    // Load / create vault data and update its location.
    match load_vault_at(&canonical_item) {
        Some(mut vault) => {
            vault.location = Some(new_location_string.clone());
            vault.save();
        }
        None => {
            let vault = Vault::new(&canonical_name, &new_location_string);
            let jot_dir = canonical_item.join(".jot");
            let _ = fs::create_dir_all(&jot_dir);
            let data_path = jot_dir.join("data");
            vault.save_to(&data_path);
        }
    }
    state
        .vaults
        .vaults
        .insert(name.to_string(), new_location_string);
    // Keep in-memory current vault in sync if it is the moved one.
    if state.vaults.current.as_deref() == Some(name) {
        if let Some(cur) = &mut state.vault {
            // Its location field should follow only if this vault's data
            // was the loaded one; the canonical move above already
            // rewrote its data file. Reloading would be ideal, but the
            // current process ends after this command.
            let _ = cur;
        }
    }
    state.save_vaults();
    println!("vault {} moved", blue(name));
    Ok(())
}

// ---------------- Vmove ----------------

fn vmove_command(
    state: &mut State,
    item: ItemKind,
    name: &str,
    vault_name: &str,
) -> AppResult<()> {
    if !state.vaults.vaults.contains_key(vault_name) {
        // NOTE: the original reports the *item* name here.
        return err(format!("vault {} doesn't exist", name));
    }
    let vault = require_vault(state)?;
    let current_path = vault.current_path();
    let current_vault_path = vault.path();
    let dest_location = state.vaults.vaults.get(vault_name).unwrap().clone();
    let dest_vault_path = Path::new(&dest_location).join(vault_name);

    if dest_vault_path == current_vault_path {
        print!(
            "{} {} already exists in vault {}",
            item.word(),
            name,
            vault_name
        );
    }

    // Same-location check happens before name validation (observed).
    if dest_vault_path == current_path {
        return err("new location is same as old location");
    }

    utils::require_valid_name(name)?;

    let (source, dest_item) = match item {
        ItemKind::Note => {
            let src = utils::note_path(&current_path, name);
            let dst_file = src.file_name().unwrap().to_str().unwrap().to_string();
            let dst = dest_vault_path.join(dst_file);
            (src, dst)
        }
        _ => {
            let src = current_path.join(name);
            let dst = dest_vault_path.join(name);
            (src, dst)
        }
    };
    if dest_item.exists() {
        return err(format!(
            "a {} named {} already exists in this location",
            item.word(),
            name
        ));
    }
    utils::move_item_to(&source, &dest_vault_path, &dest_item)?;
    println!(
        "{} {} moved to vault {}",
        item.word(),
        blue(name),
        blue(vault_name)
    );
    Ok(())
}

// ---------------- Config ----------------

fn config_command(
    state: &mut State,
    kind: Option<ConfigKind>,
    value: Option<String>,
) -> AppResult<()> {
    let Some(kind) = kind else {
        let editor = state.config.editor.clone();
        let path = state.config_path.clone();
        return open_with_editor(&editor, &path);
    };
    match value {
        None => {
            println!("{}: {}", kind.word(), blue(&state.config.get_value(kind.word())));
            Ok(())
        }
        Some(v) => {
            state.config.set_value(kind.word(), &v);
            state.save_config();
            println!("set {} to {}", blue(kind.word()), blue(&v));
            Ok(())
        }
    }
}
