new='''fn collect_details(
    current: &Path,
    directories: &mut Vec<PathBuf>,
    files: &mut Vec<PathBuf>,
) -> Result<(), String> {
    let rd = match fs::read_dir(current) {
        Ok(rd) => rd,
        Err(io) => return Err(move_error_from_io(io)),
    };
    let mut entries = Vec::new();
    for entry in rd {
        match entry {
            Ok(e) => entries.push(e.path()),
            Err(io) => return Err(move_error_from_io(io)),
        }
    }
    for entry_path in entries {
        if entry_path.is_dir() {
            directories.push(entry_path.clone());
            collect_details(&entry_path, directories, files)?;
        } else {
            // Broken symlinks and similar fail here, before any file
            // in the folder is copied.
            if let Err(io) = fs::metadata(&entry_path) {
                return Err(move_error_from_io(io));
            }
            files.push(entry_path);
        }
    }
    Ok(())
}

fn copy_dir_fs(source: &Path, dest_parent: &Path) -> Result<(), String> {
    if let Err(io) = fs::metadata(source) {
        return Err(move_error_from_io(io));
    }
    let dest_dir = dest_parent.join(source.file_name().unwrap());
    if let Err(io) = fs::create_dir(&dest_dir) {
        return Err(move_error_from_io(io));
    }
    let mut directories = Vec::new();
    let mut files = Vec::new();
    collect_details(source, &mut directories, &mut files)?;
    for dir in &directories {
        let rel = match dir.strip_prefix(source) {
            Ok(r) => r,
            Err(_) => continue,
        };
        let target = dest_dir.join(rel);
        if let Err(io) = fs::create_dir(&target) {
            return Err(move_error_from_io(io));
        }
    }
    for file in &files {
        let rel = match file.strip_prefix(source) {
            Ok(r) => r,
            Err(_) => continue,
        };
        // Symlinked files fail in the directory mover.
        if let Ok(meta) = fs::symlink_metadata(file) {
            if meta.file_type().is_symlink() {
                return Err(format!(
                    "path \\"{}\\" does not exist or you don't have access!",
                    file.display()
                ));
            }
        }
        match fs::metadata(file) {
            Ok(meta) => {
                if !meta.is_file() {
                    return Err(format!(
                        "path \\"{}\\" is not a file!",
                        file.display()
                    ));
                }
            }
            Err(io) => return Err(move_error_from_io(io)),
        }
        let target = dest_dir.join(rel);
        if let Err(io) = fs::copy(file, &target) {
            return Err(move_error_from_io(io));
        }
    }
    Ok(())
}

'''
