use crate::toml_util::{self, Value};
use std::fs;
use std::path::Path;

// State values are stored as TOML in files under the user's
// configuration and data directories. Each state type knows how
// to convert itself to and from a parsed TOML value, while this
// trait supplies the shared file handling around that conversion.
pub trait TomlState: Sized {
    fn from_value(v: &Value) -> Option<Self>;
    fn to_toml(&self) -> String;

    fn parse(contents: &str) -> Self {
        // Parsing first produces a generic TOML document. A document
        // that cannot be parsed, or whose values do not match the
        // expected state shape, is treated as corrupted data.
        let document = toml_util::parse_document(contents).ok();
        let parsed_data = document.and_then(|value| Self::from_value(&value));
        match parsed_data {
            Some(value) => value,
            None => panic!("couldn't parse data"),
        }
    }
    fn load(path: &Path) -> Self {
        let contents = match fs::read_to_string(path) {
            Ok(contents) => contents,
            Err(_) => panic!("couldn't load file"),
        };
        Self::parse(&contents)
    }

    fn save_to(&self, path: &Path) {
        let contents = self.to_toml();
        Self::write_contents(path, &contents);
    }
    fn write_contents(path: &Path, contents: &str) {
        let done = fs::write(path, contents);
        done.unwrap();
    }
}
