    used_positionals: usize,
) -> String {
    if has_suggestion {
        return smart_usage_block(bin, canonical, used_positionals);
    }
    if smart_used {
        if canonical == "__top__" {
            return usage_block_for_error(bin, canonical);
        }
        if matches!(canonical, "vault" | "note" | "folder" | "config") {
            return usage_block_for_error(bin, canonical);
        }
        // Like the suggested-flag form, but without --help: include
        // required arguments and any optional ones already used.
        let defs = arg_defs(canonical);
        let mut line = format!("{} {}", bin, canonical);
        for (idx, def) in defs.iter().enumerate() {
            let required = canonical != "list";
            if required || idx < used_positionals {
                line.push(' ');
                line.push_str(def.display);
            }
        }
        return format!("USAGE:\\n    {}\\n", line);
    }
    usage_block_for_error(bin, canonical)
}

