        .collect()
}

pub fn display_stem(path: &Path) -> String {
    let stem = path.file_stem().unwrap();
    stem.to_str().unwrap().to_string()
}

/// Prints the items below a folder as a tree.
///
/// Notes below the folder are shown at every level, as are
/// folders, while the vault's own `.jot` folder is skipped.
/// Each item is introduced by a branch showing whether more
/// items follow it at the same level, and children of a folder
/// are indented according to whether their parent was the last
/// item at its own level.
pub fn print_tree(current_path: &Path) {
    fn recurse(path: &Path, prefix: &str) {
        let dir = read_dir(path).unwrap();
        let mut peekable = dir.peekable();
        while let Some(entry) = peekable.next() {
            let entry = entry.unwrap();
            let entry_path = entry.path();
            let is_last = peekable.peek().is_none();
            let connector = if is_last { "└── " } else { "├── " };
            if entry_path.is_dir() {
                let file_name = entry_path.file_name().unwrap().to_str().unwrap().to_string();
                if file_name == ".jot" {
                    continue;
                }
                let stem = display_stem(&entry_path);
                println!("{}{}{}", prefix, connector, stem);
                let new_prefix = format!("{}{}", prefix, if is_last { "    " } else { "│   " });
                recurse(&entry_path, &new_prefix);
            } else {
                let is_note = match entry_path.extension() {
                    None => true,
                    Some(ext) => ext == "md",
                };
                if is_note {
                    let stem = display_stem(&entry_path);
                    println!(
                        "{}{}\\x1b[0;34m{}\\x1b[0m",
                        prefix, connector, stem
                    );
                }
            }
        }
    }
    recurse(current_path, "");
}

