        if op=="note": steps.append(("cmd",["note",rng.choice(names)]))
        elif op=="folder": steps.append(("cmd",["folder",rng.choice(folders)]))
        elif op=="list": steps.append(("cmd",["list"]))
        elif op=="listnote": steps.append(("cmd",["list","note"]))
        elif op=="listfolder": steps.append(("cmd",["list","folder"]))
        elif op=="chdir": steps.append(("cmd",["chdir",rng.choice(folders+["..",".","/"])]))
        elif op=="rename_note": steps.append(("cmd",["rename","note",rng.choice(names),rng.choice(names+"new") if False else rng.choice(names+["newname"])]))
        elif op=="remove_note": steps.append(("cmd",["remove","note",rng.choice(names)]))
        elif op=="move_note": steps.append(("cmd",["move","note",rng.choice(names),rng.choice(folders+["..","."])]))
        elif op=="vmove_note": steps.append(("cmd",["vmove","note",rng.choice(names),rng.choice(["v1","v2","nope"])]))
        elif op=="enter": steps.append(("cmd",["enter",rng.choice(["v1","v2","nope"])]))
        elif op=="vault_list": steps.append(("cmd",["vault"]))
        elif op=="config_get": steps.append(("cmd",["config",rng.choice(["editor","conflict"])]))
    return steps

fails=0
for seed in range(20):
    steps=gen(seed)
    r1,t1=run_scenario(ORIG, steps)
    r2,t2=run_scenario(OURS, steps)
    # Filter out results where output is vault listing with multiple vaults order random: we can compare but if sequence includes vault list with >1, may differ spuriously.
    # Detect diffs
    diffs=[]
    for a,b in zip(r1,r2):
        if a!=b: diffs.append((a,b))
    treediff=[]
    s1=dict(t1); s2=dict(t2)
    for k in sorted(set(s1)|set(s2)):
        if s1.get(k)!=s2.get(k): treediff.append((k,s1.get(k),s2.get(k)))
    # Ignore vault registry order differences in tree (content lines order) by checking as sets? Keep note.
    if diffs or treediff:
        # Check if all diffs are just vault list ordering / registry ordering
        print(f"seed {seed} diffs {len(diffs)} treediff {len(treediff)}")
        for a,b in diffs[:5]: print("  orig",a); print("  ours",b)
        for k,a,b in treediff[:5]: print("  tree",k,a,b)
        fails+=1
print("seeds with diffs",fails)
